import { requireSupabase } from '../lib/supabase';

/** Row from public.profiles. */
export interface Profile {
  id: string;
  username: string;
  color: string;
  avatar_url: string | null;
  xp: number;
  level: number;
  created_at: string;
}

/** Usernames generated by the sign-up trigger look like this until the player picks one. */
export const PLACEHOLDER_USERNAME = /^runner_[0-9a-f]{8}$/;

export const USERNAME_RULE = /^[A-Za-z0-9_]{3,20}$/;

export const TERRITORY_COLORS = ['#B7F34A', '#5BC0EB', '#FF8C42', '#B084F5', '#FF5BA7', '#FFD23F'] as const;

export async function signUp(email: string, password: string) {
  const { data, error } = await requireSupabase().auth.signUp({ email, password });
  if (error) throw error;
  return data;
}

export async function signIn(email: string, password: string) {
  const { data, error } = await requireSupabase().auth.signInWithPassword({ email, password });
  if (error) throw error;
  return data;
}

export async function signOut() {
  const { error } = await requireSupabase().auth.signOut();
  if (error) throw error;
}

export async function fetchProfile(userId: string): Promise<Profile | null> {
  const { data, error } = await requireSupabase()
    .from('profiles')
    .select('*')
    .eq('id', userId)
    .maybeSingle<Profile>();
  if (error) throw error;
  return data;
}

export async function updateProfile(
  userId: string,
  changes: Partial<Pick<Profile, 'username' | 'color' | 'avatar_url'>>,
): Promise<Profile> {
  const { data, error } = await requireSupabase()
    .from('profiles')
    .update(changes)
    .eq('id', userId)
    .select('*')
    .single<Profile>();
  if (error) {
    // 23505 = unique_violation on profiles.username
    if (error.code === '23505') throw new Error('That username is taken. Try another one.');
    throw error;
  }
  return data;
}

/** Turn Supabase/network errors into a sentence we can show on a form. */
export function authErrorMessage(error: unknown): string {
  if (error instanceof Error && error.message) {
    if (/invalid login credentials/i.test(error.message)) return 'Wrong email or password.';
    if (/user already registered/i.test(error.message)) return 'An account with this email already exists. Log in instead.';
    if (/password should be at least/i.test(error.message)) return 'Password must be at least 6 characters.';
    if (/email not confirmed/i.test(error.message)) return 'Check your inbox to confirm your email, then log in.';
    if (/network|fetch/i.test(error.message)) return 'Can’t reach the server. Check your connection.';
    return error.message;
  }
  return 'Something went wrong. Please try again.';
}
